// #84a6c7b9b86bbe3ff8e17f2c (#e17f2c) — после «שליחה מחדש» блок «בית העסק נוצר» показывает НОВУЮ ссылку, прежняя отменена.
// Кейс BIZ-LC-011 · spec: specs/business-lifecycle.md (7.1) · seed: tests/seed.admin.spec.ts (+ окно гостя).
// Данные: одноразовый бизнес «QA-AUTO-e17f2c-<stamp>» (почты example.com — письмо не уходит); удаляется в afterAll (статус נמחק).
// По приглашению не вступаем (пароль).
import * as path from 'path';
import { Page } from '@playwright/test';
import { test, expect } from '../../fixtures';
import { runStamp } from '../support/api';

const ADMIN_STATE = path.resolve(__dirname, '../../../auth/admin.json');
test.use({ storageState: ADMIN_STATE });

const stamp = runStamp();
const BUSINESS_NAME = `QA-AUTO-e17f2c-${stamp}`;
const MANAGER_EMAIL = 'qa+auto-e17f2c@example.com';

let businessId = '';

async function deleteBusiness(page: Page) {
  const loaded = page.waitForResponse((r) => r.url().includes('/rpc/admin_get_business') && r.request().method() === 'POST');
  await page.goto(`/admin/businesses/${businessId}`);
  expect((await loaded).ok()).toBeTruthy();
  const status = page.getByRole('region', { name: 'סטטוס החשבון' });
  await status.getByRole('combobox', { name: 'סטטוס חדש' }).selectOption({ label: 'נמחק' });
  await status.getByRole('button', { name: 'עדכון סטטוס' }).click();
  const saved = page.waitForResponse((r) => r.url().includes('/rpc/admin_set_business_status'));
  await page.getByRole('button', { name: 'אישור', exact: true }).click();
  expect((await saved).ok(), 'admin_set_business_status → נמחק').toBeTruthy();
  await expect(page.getByText('בית העסק נמחק')).toBeVisible();
}

test.describe('Блок «בית העסק נוצר» после повторной отправки (#84a6c7b9b86bbe3ff8e17f2c)', () => {
  test.afterAll(async ({ browser }) => {
    if (!businessId) return;
    const ctx = await browser.newContext({ storageState: ADMIN_STATE, baseURL: test.info().project.use.baseURL, locale: 'he-IL' });
    try {
      await deleteBusiness(await ctx.newPage());
    } finally {
      await ctx.close();
    }
  });

  test('после двух «שליחה מחדש» блок «בית העסק נוצר» показывает и копирует новую ссылку, прежние — «ההזמנה בוטלה» @desktop @data #84a6c7b9b86bbe3ff8e17f2c', async ({ page, context, asUser }) => {
    await context.grantPermissions(['clipboard-read', 'clipboard-write']);
    await page.goto('/admin/businesses/new');
    await expect(page.getByRole('heading', { level: 1, name: 'יצירת בית עסק' })).toBeVisible();

    const biz = page.getByRole('group', { name: 'פרטי העסק' });
    await biz.getByRole('textbox', { name: 'שם העסק (חובה)' }).fill(BUSINESS_NAME);
    await biz.getByRole('textbox', { name: 'תחום פעילות (חובה)' }).fill('QA-AUTO בדיקות');
    const contact = page.getByRole('group', { name: 'איש קשר' });
    await contact.getByRole('textbox', { name: 'שם איש הקשר (חובה)' }).fill('QA-AUTO איש קשר');
    await contact.getByRole('textbox', { name: 'תפקיד איש הקשר (חובה)' }).fill('QA-AUTO תפקיד');
    await contact.getByRole('textbox', { name: 'טלפון (חובה)' }).fill('0500000000');
    await contact.getByRole('textbox', { name: 'מייל (חובה)' }).fill('qa+auto-e17f2c-contact@example.com');
    const manager = page.getByRole('group', { name: 'מנהל/ת החשבון הראשון/ה' });
    await manager.getByRole('textbox', { name: 'שם מלא (חובה)' }).fill(`QA-AUTO מנהל ${stamp}`);
    await manager.getByRole('textbox', { name: 'מייל (חובה)' }).fill(MANAGER_EMAIL);

    const created = page.waitForResponse((r) => r.url().includes('/functions/v1/admin-create-business'));
    await page.getByRole('button', { name: 'יצירת בית העסק' }).click();
    const createdRes = await created;
    expect(createdRes.status(), 'admin-create-business').toBe(201);
    const body = (await createdRes.json()) as { business_id: string; invitation: { token: string } };
    businessId = body.business_id;
    test.info().annotations.push({ type: 'test-data', description: `business ${BUSINESS_NAME} ${businessId} (удаляется в afterAll)` });
    await page.waitForURL(`**/admin/businesses/${businessId}`);

    const origin = new URL(page.url()).origin;
    const linkOf = (token: string) => `${origin}/invite/${token}`;
    const createdBlock = page.getByRole('region', { name: 'בית העסק נוצר' });
    const inviteRow = page.getByRole('region', { name: 'הזמנות' }).getByRole('row').filter({ hasText: MANAGER_EMAIL });
    const tokens = [body.invitation.token];
    await expect(createdBlock.getByText(linkOf(tokens[0]), { exact: true })).toBeVisible();

    // Две повторные отправки без перезагрузки страницы (как при ручной проверке 21.10).
    for (let i = 1; i <= 2; i++) {
      const resent = page.waitForResponse((r) => r.url().includes('/functions/v1/resend-invitation'));
      await inviteRow.getByRole('button', { name: 'שליחה מחדש' }).click();
      const res = await resent;
      expect(res.status(), `resend-invitation #${i}`).toBe(200);
      const token = ((await res.json()) as { invitation: { token: string } }).invitation.token;
      expect(token, `новый токен после отправки #${i}`).toBeTruthy();
      expect(tokens).not.toContain(token);
      tokens.push(token);

      // Источник: «מה רצוי» #e17f2c — блок показывает актуальную ссылку, не отменённую.
      await expect(createdBlock.getByText(linkOf(token), { exact: true })).toBeVisible();
      for (const old of tokens.slice(0, -1)) await expect(createdBlock.getByText(linkOf(old))).toHaveCount(0);
      await expect(inviteRow).toContainText('ממתינה');
      await expect(inviteRow.getByRole('status')).toHaveText('נוצר קישור חדש, אך שליחת המייל נכשלה. אפשר להעתיק אותו.');
    }

    const latest = linkOf(tokens[tokens.length - 1]);
    await createdBlock.getByRole('button', { name: 'העתקת הקישור' }).click();
    await expect(createdBlock.getByRole('status')).toHaveText('הקישור הועתק');
    expect(await page.evaluate(() => navigator.clipboard.readText()), 'скопирована новая ссылка').toBe(latest);

    // Треб.8 «שליחה חדשה מבטלת את הקודמת»: прежние ссылки отменены, новая открывает форму.
    const guest = await asUser('guest');
    for (const old of tokens.slice(0, -1)) {
      await guest.goto(`/invite/${old}`);
      await expect(guest.getByRole('heading', { level: 1, name: 'ההזמנה בוטלה' })).toBeVisible();
      await expect(guest.getByRole('textbox')).toHaveCount(0);
    }
    await guest.goto(latest);
    await expect(guest.getByRole('heading', { level: 1, name: 'הצטרפות לחשבון העסק' })).toBeVisible();
    await expect(guest.getByRole('textbox', { name: 'סיסמה', exact: true })).toBeVisible();
  });
});
